import { test } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25.5, C: 33.33, D: 0.99 }
const pricing = { priceOf: async (sku) => prices[sku] }

async function withApp(fn) {
  const server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  const base = `http://localhost:${server.address().port}`
  try { await fn(base) } finally { server.close() }
}

async function totalFor(items) {
  let total
  await withApp(async (base) => {
    const res = await fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify({ items }) })
    assert.equal(res.status, 201)
    total = (await res.json()).total
  })
  return total
}

// Characterization tests: pin current behaviour of order totals.
test('no discount below threshold', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 3 }]), 30)
})

test('sums multiple lines', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 2 }, { sku: 'B', qty: 2 }]), 71)
})

test('exactly 100 gets no discount (threshold is strictly greater)', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }]), 100)
})

test('just over 100 gets 10% off', async () => {
  // 100.99 * 0.9 = 90.891 -> 90
  assert.equal(await totalFor([{ sku: 'A', qty: 10 }, { sku: 'D', qty: 1 }]), 90)
})

test('large order gets 10% off', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 50 }]), 450)
})

test('very large order still gets only a flat 10% (no extra tiers)', async () => {
  assert.equal(await totalFor([{ sku: 'A', qty: 1000 }]), 9000)
})

test('total is truncated (floored) to whole euros, not rounded', async () => {
  // 33.33 * 4 = 133.32 -> 119.988 -> 119 (rounding would give 120)
  assert.equal(await totalFor([{ sku: 'C', qty: 4 }]), 119)
  // 0.99 * 5 = 4.95 -> 4
  assert.equal(await totalFor([{ sku: 'D', qty: 5 }]), 4)
})
EOF
